### Result
{
  "result": "PASS: 3 periodos e ordem visual cronologica",
  "rows": [
    "2 / span 1",
    "22 / span 1",
    "10 / span 1"
  ]
}
### Ran Playwright code
```js
await page.evaluate('() => {const cards=[...document.querySelectorAll(".block")];if(cards.length!==3||document.querySelectorAll(".empty").length!==0)throw Error("Periodos incompletos");const rows=cards.map(e=>e.style.gridRow);if(!rows.some(x=>x.startsWith("2 /"))||!rows.some(x=>x.startsWith("10 /"))||!rows.some(x=>x.startsWith("22 /")))throw Error("Posicoes incorretas");return {result:"PASS: 3 periodos e ordem visual cronologica",rows};}');
```

